import 'package:material_ui/material_ui.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../auth/presentation/auth_controller.dart';
class AdminUser{AdminUser.fromJson(Map<String,dynamic>j):id=j['id'] as String,name=j['fullName'] as String,email=j['email'] as String,role=j['role'].toString(),status=j['accountStatus'].toString();final String id,name,email,role,status;}
final adminUsersProvider=FutureProvider.autoDispose((ref)async{final r=await ref.watch(apiClientProvider).dio.get<List<dynamic>>('/api/admin/users');return r.data!.map((e)=>AdminUser.fromJson(e)).toList();});
class AdminUsersPage extends ConsumerWidget{const AdminUsersPage({super.key});@override Widget build(BuildContext context,WidgetRef ref){final s=ref.watch(adminUsersProvider);return Scaffold(appBar:AppBar(title:const Text('إدارة المستخدمين')),body:s.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(_,_)=>const Center(child:Text('تعذر تحميل المستخدمين.')),data:(items)=>ListView.builder(itemCount:items.length,itemBuilder:(_,i)=>Card(child:ListTile(title:Text(items[i].name),subtitle:Text(items[i].email),trailing:Text(items[i].status))))));}}
